#include "gameos/core/Kernel.hpp"
namespace gameos::core { bool Kernel::boot(BootConfig c){config_=std::move(c);for(auto*s:subsystems_)if(!s->start(config_)){panic(std::string("Failed to start subsystem: ")+s->name());return false;}frame_=0;running_=true;return true;} void Kernel::runFrame(double dt){if(!running_)return;TickContext c{dt,++frame_};for(auto*s:subsystems_)s->tick(c);} void Kernel::shutdown()noexcept{if(!running_)return;for(auto i=subsystems_.rbegin();i!=subsystems_.rend();++i)(*i)->stop();running_=false;} void Kernel::addSubsystem(ISubsystem&s){if(!running_)subsystems_.push_back(&s);} void Kernel::setPanicHandler(PanicHandler h){panicHandler_=std::move(h);} void Kernel::panic(const std::string&m){if(panicHandler_)panicHandler_(m);} }
